function icon(k){return '<svg class="ico" viewBox="0 0 24 24" aria-hidden="true">'+(paths[k]||paths.cube)+'</svg>'}
const esc=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const pages={home:['Ringkasan','grid'],agents:['AI Agent','bot'],services:['Status layanan','server'],connections:['API & koneksi','key'],tasks:['Tugas otomatis','bolt'],logs:['Log aktivitas','activity'],checks:['Checklist setup','checklist'],help:['Troubleshooting','tool'],settings:['Konfigurasi','settings']};
const schema={agents:{one:'agent',detail:'Peran',slot:'Host',statuses:['Aktif','Siaga','Berhenti','Gangguan']},services:{one:'layanan',detail:'Fungsi',slot:'Host',statuses:['Sehat','Gangguan','Berhenti']},connections:{one:'koneksi',detail:'Referensi key di VPS',slot:'Penyedia',statuses:['Terhubung','Belum diuji','Gangguan']},tasks:{one:'tugas',detail:'Jadwal',slot:'Pelaksana',statuses:['Terjadwal','Dijeda','Gangguan']}};
const now=new Date();const isoAgo=m=>new Date(now.getTime()-m*60000).toISOString();const make=(name,detail,slot,status)=>({name,detail,slot,status});
const demo={version:1,updatedAt:isoAgo(0),infra:{name:'Hermes Production',host:'vps-hermes-01',os:'Ubuntu 24.04',cpu:24,ram:48,disk:36},
agents:[make('Hermes Core','Orkestrasi agent','VPS utama','Aktif'),make('Workflow Agent','Eksekusi alur kerja','Hermes','Aktif'),make('Monitor Agent','Pemantauan layanan','VPS utama','Aktif'),make('Research Agent','Riset dan analisis','Hermes','Siaga')],
services:[make('Hermes Gateway','Gerbang permintaan','VPS utama','Sehat'),make('Penjadwal','Pengatur jadwal tugas','Hermes','Sehat'),make('Penyimpanan','Basis data agent','VPS utama','Sehat')],
connections:[make('OpenServ','OPENSERV_API_KEY','OpenServ','Terhubung'),make('Model inference','MODEL_API_KEY','Endpoint model','Terhubung')],
tasks:[make('Periksa layanan','Setiap 5 menit','Monitor Agent','Terjadwal'),make('Cadangkan konfigurasi','Setiap hari, 02.00 WIB','Workflow Agent','Terjadwal'),make('Ringkasan harian','Setiap hari, 07.00 WIB','Hermes Core','Terjadwal')],
logs:[['Pemeriksaan layanan selesai','Monitor Agent','Berhasil',3],['Cadangan konfigurasi tersimpan','Workflow Agent','Berhasil',15],['Koneksi API diperbarui','Hermes Core','Info',34],['Agent menunggu tugas','Research Agent','Info',52]].map(([message,source,level,m])=>({message,source,level,at:isoAgo(m)})),
checks:[{label:'Catat host dan sistem operasi VPS',done:true},{label:'Daftarkan agent Hermes',done:true},{label:'Periksa referensi API key di VPS',done:false},{label:'Uji jadwal otomatisasi dan zona waktu',done:false},{label:'Verifikasi endpoint pemantauan',done:false}]};
const key='ruang-agen-workspace-v1',blank=()=>structuredClone(demo);
function plain(s,max=220){return typeof s==='string'&&s.trim()&&s.length<=max}
function stamp(s){return typeof s==='string'&&Number.isFinite(Date.parse(s))}
function validate(x){
 if(!x||x.version!==1||!stamp(x.updatedAt)||!x.infra)throw Error('Versi, waktu pembaruan, atau infrastruktur tidak valid.');
 const f=x.infra;if(!['name','host','os'].every(k=>plain(f[k]))||!['cpu','ram','disk'].every(k=>Number.isFinite(f[k])&&f[k]>=0&&f[k]<=100))throw Error('Periksa identitas VPS dan persentase sumber daya (0–100).');
 const result={version:1,updatedAt:x.updatedAt,infra:Object.fromEntries(['name','host','os','cpu','ram','disk'].map(k=>[k,f[k]]))};
 for(const [k,v] of Object.entries(schema)){if(!Array.isArray(x[k])||x[k].length>2000||!x[k].every(r=>r&&['name','detail','slot'].every(a=>plain(r[a]))&&v.statuses.includes(r.status)))throw Error('Periksa daftar '+pages[k][0]+'.');result[k]=x[k].map(r=>make(r.name,r.detail,r.slot,r.status))}
 if(!Array.isArray(x.logs)||x.logs.length>5000||!x.logs.every(l=>l&&plain(l.message,500)&&plain(l.source)&&['Info','Berhasil','Peringatan','Gagal'].includes(l.level)&&stamp(l.at)))throw Error('Format log aktivitas tidak valid.');
 if(!Array.isArray(x.checks)||x.checks.length>500||!x.checks.every(c=>c&&plain(c.label)&&typeof c.done==='boolean'))throw Error('Format checklist tidak valid.');
 result.logs=x.logs.map(({message,source,level,at})=>({message,source,level,at})).sort((a,b)=>Date.parse(b.at)-Date.parse(a.at));result.checks=x.checks.map(({label,done})=>({label,done}));return result;
}
function read(){try{const s=JSON.parse(localStorage.getItem(key));return {data:validate(s.data),mode:['Contoh','Manual','Endpoint'].includes(s.mode)?s.mode:'Manual',url:typeof s.url==='string'?s.url:'',auto:!!s.auto}}catch{return {data:blank(),mode:'Contoh',url:'',auto:false}}}
let state=read(),page='home',query='',filter='',syncing=false,syncError='',timer,saveAction;
const data=()=>state.data;
function persist(){try{localStorage.setItem(key,JSON.stringify(state))}catch{toast('Penyimpanan browser penuh atau tidak tersedia. Ekspor data sebelum menutup halaman.')}}
function toast(t){const n=$('#toast');n.textContent=t;n.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>n.classList.remove('show'),4000)}
function logChange(message){data().logs.unshift({message,source:'Paraf AI',level:'Info',at:new Date().toISOString()});data().logs=data().logs.slice(0,5000);data().updatedAt=new Date().toISOString();state.mode='Manual';state.auto=false;syncError='';persist()}
const tint=['violet','blue','teal','amber'], symbols=['bot','bolt','activity','layer'];
function tile(k,color){return '<span class="tile '+color+'">'+icon(k)+'</span>'}
function badge(s){const cl=['Aktif','Sehat','Terhubung','Terjadwal','Berhasil'].includes(s)?'green':['Siaga','Belum diuji','Peringatan'].includes(s)?'yellow':['Gangguan','Gagal'].includes(s)?'red':'gray';return '<span class="badge '+cl+'"><i class="dot"></i>'+esc(s)+'</span>'}
function nav(k){return '<button class="nav '+(page===k?'active':'')+'" '+(page===k?'aria-current="page"':'')+' data-go="'+k+'">'+icon(pages[k][1])+pages[k][0]+'</button>'}
const btn=(label,act,ic='',cls='button')=>'<button type="button" class="'+cls+'" data-action="'+act+'">'+(ic?icon(ic):'')+label+'</button>';
const goBtn=(k,t='Lihat semua')=>'<button class="textbtn" data-go="'+k+'">'+t+'</button>';
function topbar(title,subtitle,action=''){return '<div class="titlebar"><div><h1>'+title+'</h1><p class="sub">'+subtitle+'</p></div>'+action+'</div>'}
function panel(title,ic,body,action=''){return '<section class="panel"><div class="panelhead"><div class="sectiontitle">'+icon(ic)+'<h2>'+title+'</h2></div>'+action+'</div>'+body+'</section>'}
function localTime(iso,full=false){return new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Jakarta',...(full?{day:'numeric',month:'short',year:'numeric'}:{}),hour:'2-digit',minute:'2-digit'}).format(new Date(iso))}
function render(){
 $('#side').innerHTML='<a class="brand" href="../#studio" aria-label="Kembali ke Studio Paraf AI"><img src="../wordmark.svg" alt="Paraf AI"></a><div class="navlabel">Ruang kerja</div>'+['home','agents','services','connections','tasks','logs'].map(nav).join('')+'<div class="navlabel">Pemeliharaan</div>'+['checks','help','settings'].map(nav).join('')+'<div class="sidefoot"><div class="env"><span class="envicon">'+icon('terminal')+'</span><div><b>VPS &amp; Hermes</b><small>Ruang kerja pribadi</small></div></div></div>';
 $('#crumbicon').innerHTML=icon('layer');$('#crumb').textContent=pages[page][0];$('#source').textContent=state.mode==='Contoh'?'Data contoh':state.mode==='Endpoint'?'Snapshot VPS':'Data manual';
 document.title=pages[page][0]+' · Paraf AI';$('#main').innerHTML=page==='home'?overview():schema[page]?records():page==='logs'?logsPage():page==='checks'?checkPage():page==='help'?helpPage():settingsPage();
}
function hero(){const f=data().infra;return '<section class="hero"><paraf-orb class="heroart" aria-hidden="true"></paraf-orb><button type="button" class="motion-control" data-motion aria-label="Jeda animasi">Ⅱ</button><div class="heroText"><div class="overline"><i></i> INFRASTRUKTUR VPS</div><h2>'+esc(f.name)+'</h2><div class="herometa">'+icon('terminal')+esc(f.host)+' &nbsp;·&nbsp; '+esc(f.os)+'</div><div class="resources">'+[['CPU','cpu'],['Memori','ram'],['Disk','disk']].map(([n,k])=>'<div><div class="reshead"><span>'+n+'</span><b>'+f[k]+'%</b></div><div class="bar"><i style="width:'+f[k]+'%"></i></div></div>').join('')+'</div></div></section>'}
const charts=['1,26 9,26 16,18 23,22 32,14 38,17 46,8 54,13 61,8 70,8 78,2','1,22 11,20 18,23 24,13 32,16 39,12 47,17 55,8 63,13 71,7 78,9','1,25 9,25 15,21 24,21 30,18 38,22 45,14 52,16 62,7 69,10 78,4','1,25 10,23 18,25 26,19 34,20 42,15 50,19 56,13 65,14 72,9 78,10'];
function spark(i){const c=['#7ca366','#69aa8a','#92b566','#c3ab65'][i];return '<svg class="spark" viewBox="0 0 80 34" aria-label="Tendensi contoh"><defs><linearGradient id="s'+i+'" x1="0" x2="0" y1="0" y2="1"><stop stop-color="'+c+'" stop-opacity=".25"/><stop offset="1" stop-color="'+c+'" stop-opacity="0"/></linearGradient></defs><polygon points="1,34 '+charts[i]+' 78,34" fill="url(#s'+i+')"/><polyline points="'+charts[i]+'" stroke="'+c+'" fill="none" stroke-width="2" stroke-linejoin="round"/></svg>'}
function metrics(){return '<div class="statgrid">'+[['agents','Agent aktif','bot','violet','Aktif','agent'],['services','Layanan sehat','server','teal','Sehat','layanan'],['tasks','Tugas otomatis','bolt','blue','Terjadwal','tugas'],['connections','Koneksi aktif','link','amber','Terhubung','koneksi']].map(([k,n,ic,col,status,noun],i)=>'<button class="card" data-go="'+k+'"><span class="labelicon">'+tile(ic,col)+n+'</span><div class="statline"><div><span class="number">'+data()[k].filter(r=>r.status===status).length+'</span><span class="micro">dari '+data()[k].length+' '+noun+'</span></div>'+(state.mode==='Contoh'?spark(i):'')+'</div></button>').join('')+'</div>'}
function rows(k,short){const list=data()[k].map((r,i)=>({r,i})).filter(({r})=>short||((!filter||r.status===filter)&&[r.name,r.detail,r.slot].join(' ').toLowerCase().includes(query.toLowerCase())));return '<div class="tablewrap"><table class="'+(short?'overview':'')+'"><thead><tr><th>Nama '+schema[k].one+'</th><th class="hostcol">'+schema[k].slot+'</th><th>Status</th>'+(short?'':'<th>Ubah</th>')+'</tr></thead><tbody>'+(short?list.slice(0,4):list).map(({r,i})=>'<tr><td><div class="row">'+tile(k==='agents'?symbols[i%4]:pages[k][1],tint[i%4])+'<div><div class="name">'+esc(r.name)+'</div><div class="meta">'+esc(r.detail)+'</div></div></div></td><td class="hostcol">'+esc(r.slot)+'</td><td>'+badge(r.status)+'</td>'+(short?'':'<td><button class="iconbtn" data-edit="'+i+'" aria-label="Ubah '+esc(r.name)+'">'+icon('pen')+'</button></td>')+'</tr>').join('')+'</tbody></table>'+(!list.length?'<div class="empty">Tidak ada '+schema[k].one+' yang sesuai.</div>':'')+'</div>'}
function logRows(short){const logs=data().logs.filter(l=>short||((!filter||l.level===filter)&&(l.message+' '+l.source).toLowerCase().includes(query.toLowerCase())));return '<div class="loglist">'+(short?logs.slice(0,4):logs).map((l,i)=>'<div class="logrow">'+tile(l.level==='Berhasil'?(i%2?'database':'check'):l.level==='Info'?'activity':'alert',l.level==='Berhasil'?(i%2?'violet':'teal'):l.level==='Info'?'blue':'amber')+'<div><div class="name">'+esc(l.message)+'</div><div class="meta">'+esc(l.source)+(short?'':' · '+esc(l.level))+'</div></div><time class="logtime" datetime="'+esc(l.at)+'" title="'+localTime(l.at,true)+' WIB">'+localTime(l.at,!short)+(short?'':' WIB')+'</time></div>').join('')+(!logs.length?'<div class="empty">Belum ada aktivitas yang sesuai.</div>':'')+'</div>'}
function overview(){return topbar('Ringkasan operasional','Pantau agent, layanan, dan otomatisasi dalam satu ruang kerja.',btn('Konfigurasi','settings','settings'))+hero()+metrics()+'<div class="panels">'+panel('Daftar agent','bot',rows('agents',true),goBtn('agents'))+panel('Aktivitas terbaru','clock',logRows(true),goBtn('logs'))+'</div><div class="below">'+panel('Tugas otomatis','bolt',rows('tasks',true),goBtn('tasks'))+'</div><p class="meta">Pembaruan '+localTime(data().updatedAt,true)+' WIB</p>'}
function searchbar(options){return '<div class="tools"><input id="search" aria-label="Cari data" placeholder="Cari nama atau keterangan…" value="'+esc(query)+'"><select id="filter" aria-label="Filter status"><option value="">Semua status</option>'+options.map(v=>'<option '+(filter===v?'selected':'')+'>'+v+'</option>').join('')+'</select></div>'}
const subtitles={agents:'Kelola identitas, peran, dan status agent di ruang kerja.',services:'Pantau status layanan yang mendukung Hermes di VPS.',connections:'Catat koneksi dan nama variabel API key yang digunakan di VPS.',tasks:'Kelola catatan jadwal dan pelaksana tugas otomatis.'};
function records(){return topbar(pages[page][0],subtitles[page],btn('Tambah '+schema[page].one,'new','plus','primary'))+searchbar(schema[page].statuses)+'<section class="panel" id="results">'+rows(page,false)+'</section>'}
function logsPage(){return topbar('Log aktivitas','Telusuri peristiwa agent dan perubahan konfigurasi dalam WIB.')+searchbar(['Info','Berhasil','Peringatan','Gagal'])+'<section class="panel" id="results">'+logRows(false)+'</section>'}
function checkPage(){const a=data().checks;return topbar('Checklist setup','Tandai langkah yang sudah Anda verifikasi pada VPS dan Hermes.',btn('Tambah langkah','newcheck','plus','primary'))+panel('Persiapan lingkungan','checklist',a.map((c,i)=>'<label class="checkrow"><input type="checkbox" data-check="'+i+'" '+(c.done?'checked':'')+'><span class="'+(c.done?'done':'')+'">'+esc(c.label)+'</span></label>').join('')||'<p class="empty">Belum ada langkah.</p>','<span class="count">'+a.filter(c=>c.done).length+' / '+a.length+' selesai</span>')}
const tips=[['Agent tidak merespons','Periksa apakah proses Hermes berjalan pada host yang tercatat. Cocokkan waktu kejadian dengan log agent dan pastikan penyedia model dapat diakses dari VPS.'],['Layanan melaporkan gangguan','Periksa penggunaan CPU, memori, dan disk pada VPS. Buka log layanan terkait untuk menemukan kesalahan pertama sebelum memulai ulang proses.'],['API key ditolak','Cocokkan nama variabel di API & koneksi dengan konfigurasi proses di VPS. Periksa izin dan masa berlaku key di penyedia, lalu muat ulang konfigurasi proses.'],['Tugas tidak berjalan sesuai jadwal','Cocokkan jadwal dan zona waktu pada penjadwal di VPS. Pastikan tugas aktif serta agent pelaksana tersedia. Periksa log penjadwal pada waktu yang diharapkan.'],['Snapshot VPS gagal dimuat','Buka Konfigurasi lalu periksa URL HTTPS dan format JSON. Endpoint harus mengizinkan permintaan CORS dari asal situs ini. Ekspor JSON untuk melihat format yang didukung. Lihat waktu pembaruan untuk mengenali snapshot lama.']];
function helpPage(){return topbar('Troubleshooting','Pilih gejala yang Anda temui untuk melihat langkah pemeriksaan.')+panel('Panduan pemeriksaan','book',tips.map(([a,b])=>'<details><summary>'+a+'</summary><p>'+b+'</p></details>').join(''))}
function settingsPage(){const f=data().infra;return topbar('Konfigurasi','Perbarui identitas VPS, sumber pemantauan, dan cadangan ruang kerja.')+'<div class="settings">'+panel('Infrastruktur VPS','server','<div class="settingbody"><div class="name">'+esc(f.name)+'</div><p class="helper">'+esc(f.host)+' · '+esc(f.os)+'</p>'+btn('Edit infrastruktur','infra','pen')+'</div>')+panel('Sumber pemantauan','link','<div class="settingbody"><p class="helper">Gunakan endpoint HTTPS milik Anda yang mengembalikan snapshot JSON sesuai format ekspor. Izinkan akses CORS dari situs ini. Simpan kredensial di VPS.</p><form id="feedForm"><label class="field">URL endpoint<input id="feedUrl" type="url" required placeholder="https://vps.anda.id/status.json" value="'+esc(state.url)+'"></label><label class="row"><input id="auto" type="checkbox" '+(state.auto?'checked':'')+'> Perbarui setiap 60 detik saat dashboard terbuka</label><p class="helper">Sinkronisasi mengganti data dashboard dengan snapshot endpoint. Perubahan manual akan menjeda pembaruan otomatis.</p><div class="tools"><button class="primary" '+(syncing?'disabled':'')+'>'+icon('refresh')+(syncing?'Memuat…':'Muat snapshot')+'</button>'+(state.url?btn('Putuskan endpoint','disconnect'):'')+'</div><p id="syncFeedback" class="feedback" role="status">'+esc(syncError)+'</p></form><p class="meta">Snapshot terakhir · '+localTime(data().updatedAt,true)+' WIB</p></div>')+panel('Data ruang kerja','database','<div class="settingbody"><p class="helper">Perubahan tersimpan di browser ini. Ekspor JSON sebagai cadangan atau contoh format endpoint. Impor untuk mengganti isi dashboard. Gunakan nama variabel sebagai referensi API key.</p><div class="tools">'+btn('Ekspor JSON','export','file')+btn('Impor JSON','import','database')+'<input id="importFile" type="file" accept=".json,application/json" hidden></div></div>')+'</div>'}
function field(label,name,value='',type='text',extra=''){return '<label class="field">'+label+'<input name="'+name+'" type="'+type+'" value="'+esc(value)+'" required '+(type==='number'?'min="0" max="100" step="any"':'maxlength="220"')+' '+extra+'></label>'}
function modal(title,html,action,label='Simpan',more=''){const d=$('#dialog');$('#modalTitle').textContent=title;$('#fields').innerHTML=html;$('#actions').innerHTML=more+btn('Batal','cancel')+'<button class="primary" type="submit">'+label+'</button>';saveAction=action;if(!d.open)d.showModal()}
function change(message){logChange(message);render();toast('Perubahan tersimpan di browser ini.')}
function editRecord(index){const k=page,s=schema[k],r=data()[k][index]||make('','','',s.statuses[0]);modal((index===undefined?'Tambah ':'Ubah ')+s.one,field('Nama '+s.one,'name',r.name)+field(s.detail,'detail',r.detail)+(k==='connections'?'<p class="helper">Contoh referensi: OPENSERV_API_KEY. Nilai rahasia tetap di VPS.</p>':'')+field(s.slot,'slot',r.slot)+'<label class="field">Status<select name="status">'+s.statuses.map(v=>'<option '+(r.status===v?'selected':'')+'>'+v+'</option>').join('')+'</select></label><p class="helper">Perubahan ini memperbarui catatan dashboard.</p>',fd=>{const item=make(fd.name,fd.detail,fd.slot,fd.status);if(index===undefined)data()[k].push(item);else data()[k][index]=item;change((index===undefined?'Menambahkan ':'Memperbarui ')+s.one+' '+fd.name)},'Simpan',index===undefined?'':btn('Hapus','delete-'+index,'','button danger'))}
function editInfra(){const f=data().infra;modal('Edit infrastruktur',field('Nama lingkungan','name',f.name)+field('Hostname','host',f.host)+field('Sistem operasi','os',f.os)+[['CPU (%)','cpu'],['Memori (%)','ram'],['Disk (%)','disk']].map(([n,k])=>field(n,k,f[k],'number')).join(''),fd=>{data().infra={...fd,cpu:Number(fd.cpu),ram:Number(fd.ram),disk:Number(fd.disk)};change('Memperbarui infrastruktur VPS')})}
function go(k){document.body.classList.remove('open');if(page===k)return;location.hash=k}
function route(){const k=location.hash.slice(1);page=Object.hasOwn(pages,k)?k:'home';query='';filter='';render();window.scrollTo(0,0)}
function download(){const a=document.createElement('a');const u=URL.createObjectURL(new Blob([JSON.stringify(data(),null,2)],{type:'application/json'}));a.href=u;a.download='ruang-agen.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function importFile(file){if(!file)return;try{if(file.size>2e6)throw Error('Batas berkas 2 MB.');const next=validate(JSON.parse(await file.text()));modal('Ganti data ruang kerja?','<p>Impor '+esc(file.name)+' dengan '+next.agents.length+' agent dan '+next.tasks.length+' tugas. Isi dashboard saat ini akan diganti.</p>',()=>{state.data=next;state.mode='Manual';state.auto=false;persist();render();toast('Data berhasil diimpor.')},'Impor data')}catch(e){toast('Gagal mengimpor. '+e.message)}}
let revision=0;
async function sync(url,auto,manual){
 if(syncing)return;const current=revision,old=data(),oldUpdate=old.updatedAt;let timeout;syncing=true;
 try{const u=new URL(url);if(u.protocol!=='https:'||u.username||u.password||u.search||u.hash)throw Error('Gunakan URL HTTPS tanpa kredensial, parameter, atau fragmen.');
 if(manual&&page==='settings'){$('#feedForm .primary').disabled=true;$('#syncFeedback').textContent='Mengambil snapshot…'}
 const ctl=new AbortController();timeout=setTimeout(()=>ctl.abort(),12000);const res=await fetch(u,{credentials:'omit',referrerPolicy:'no-referrer',cache:'no-store',signal:ctl.signal});if(!res.ok)throw Error('Endpoint mengembalikan HTTP '+res.status+'.');const raw=await res.text();if(raw.length>2e6)throw Error('Snapshot melebihi 2 MB.');const next=validate(JSON.parse(raw));
 if(current!==revision||data()!==old||old.updatedAt!==oldUpdate||$('#dialog').open)throw Error('Ruang kerja berubah saat pemuatan. Coba kembali.');
 state={data:next,mode:'Endpoint',url:u.href,auto};persist();syncError='';if(manual)toast('Snapshot berhasil dimuat.');
 }catch(e){syncError='Gagal memuat snapshot. '+(e.name==='AbortError'?'Waktu koneksi habis.':e instanceof TypeError?'Periksa URL, jaringan, dan izin CORS endpoint.':e.message);if(!manual)toast('Sinkronisasi gagal. Snapshot terakhir masih ditampilkan.')}
 finally{clearTimeout(timeout);syncing=false;if(!$('#dialog').open){if(syncError&&manual&&page==='settings'){$('#syncFeedback').textContent=syncError;$('#feedForm .primary').disabled=false}else render()}}
}
document.addEventListener('click',e=>{
 const el=e.target.closest('button');if(!el)return;if(el.dataset.go)return go(el.dataset.go);if(el.dataset.edit!==undefined)return editRecord(Number(el.dataset.edit));
 const act=el.dataset.action;if(act==='settings')go('settings');if(act==='cancel')$('#dialog').close();if(act==='new')editRecord();if(act==='infra')editInfra();if(act==='newcheck')modal('Tambah langkah setup',field('Langkah pemeriksaan','label'),fd=>{data().checks.push({label:fd.label,done:false});change('Menambahkan langkah setup')});if(act==='export')download();if(act==='import')$('#importFile').click();if(act==='disconnect'){revision++;state.url='';state.auto=false;state.mode='Manual';syncError='';persist();render();toast('Endpoint diputus. Snapshot terakhir tersimpan.')}
 if(act?.startsWith('delete-')){const idx=Number(act.slice(7)),k=page,name=data()[k][idx].name;modal('Hapus catatan?','<p>Hapus '+esc(name)+' dari dashboard ini?</p>',()=>{data()[k].splice(idx,1);change('Menghapus catatan '+name)},'Hapus')}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;$('#results').innerHTML=page==='logs'?logRows(false):rows(page,false)}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='filter'){filter=t.value;$('#results').innerHTML=page==='logs'?logRows(false):rows(page,false)}if(t.dataset.check!==undefined){data().checks[Number(t.dataset.check)].done=t.checked;change('Memperbarui checklist setup')}if(t.id==='importFile'){importFile(t.files[0]);t.value=''}});
$('#form').addEventListener('submit',e=>{e.preventDefault();const form=e.target;for(const input of form.querySelectorAll('input[required]')){if(!input.value.trim()){input.setCustomValidity('Isi kolom ini.');input.reportValidity();input.setCustomValidity('');return}}const fd=Object.fromEntries([...new FormData(form)].map(([k,v])=>[k,String(v).trim()]));saveAction(fd);$('#dialog').close()});
document.addEventListener('submit',e=>{if(e.target.id==='feedForm'){e.preventDefault();sync($('#feedUrl').value.trim(),$('#auto').checked,true)}});
$('#close').onclick=()=>$('#dialog').close();$('#menu').onclick=()=>document.body.classList.add('open');$('#shade').onclick=()=>document.body.classList.remove('open');document.addEventListener('keydown',e=>{if(e.key==='Escape')document.body.classList.remove('open')});
window.addEventListener('hashchange',route);window.addEventListener('storage',e=>{if(e.key===key){revision++;state=read();if($('#dialog').open)$('#dialog').close();render()}});route();
setInterval(()=>{if(state.auto&&state.url&&!document.hidden&&!$('#dialog').open&&page!=='settings')sync(state.url,true,false)},60000);
